    # The expected span should cover the whole URL
    spans = list(text.spans)
    print(f"Spans: {spans}")

    # We expect a span with style "repr.url"
    url_spans = [span for span in spans if span.style == "repr.url"]
    if not url_spans:
        print("FAILED: No url span found")
    else:
        for span in url_spans:
            print(f"Found url span: {span}")
            if span.start == 0 and span.end == len("https://user:pass@example.com"):
                print("SUCCESS: URL with @ is fully highlighted")
            else:
                print(f"FAILED: URL span does not cover the whole URL. Start: {span.start}, End: {span.end}")

if __name__ == "__main__":
    test_url_with_at()

